// Üretilen dosya: tool/ozgun/uret.py. Sanat · Baskı resim, gravür, litografi, illüstrasyon, karikatür ve çizgi roman sanatı (ağaç baskı, taş baskı, serigrafi, ukiyo-e, Dürer, Hokusai, çizerlik terimleri) (kolay).
const ozArt16Kolay = <(String, String, List<String>, String)>[
  ('Yüksek baskı tekniğinde mürekkebin kâğıda aktarılma prensibi kalıp yüzeyinin hangi bölgesi üzerinden gerçekleşir?', 'Kazınmadan yüksekte bırakılan sırt yüzeylerinden', ['Oyularak çukurlaştırılan derin kanalların içinden', 'Kimyasal zamkla suyu tutan gözenekli taş dokusundan', 'İpek dokumanın açık bırakılan gözenek boşluklarından'], 'Yüksek baskıda (ksilografi, linol) merdane yalnızca oyulmadan yüksekte kalan yüzeyleri boyar ve kâğıda bu kısımlar basılır.'),
  ('Bir öğrencinin linolyum kalıba \'BİLİM\' sözcüğünü doğru okunacak biçimde basabilmesi için harfleri kalıp üzerine nasıl işlemesi gerekir?', 'Soldan sağa ayna görüntüsü oluşturacak şekilde ters kazımalıdır', ['Kitap sayfasında okunduğu yönle birebir aynı düzende oymalıdır', 'Harfleri yukarıdan aşağıya dikey sütun halinde düz yerleştirmelidir', 'Yalnızca sesli harfleri ters, sessiz harfleri düz yönde kesmelidir'], 'Yüksek ve çukur baskı kalıplarında görüntü kâğıda ters (ayna simetrisiyle) geçtiği için yazıların kalıba ters işlenmesi zorunludur.'),
  ('Soğuk bir atölyede sertleştiği için bıçağın kaymasına yol açan linolyum levhasını kazıma öncesinde güvenli biçimde yumuşatmak isteyen bir sanatçı ne yapmalıdır?', 'Plakayı ılık bir yüzeyde hafifçe ısıtarak esnekliğini artırmalıdır', ['Levhayı bir gece boyunca saf aseton dolu küvette bekletmelidir', 'Yüzeye kalın bir tabaka Arap zamkı ve nitrik asit sürmelidir', 'Kalıbı dondurucuda soğutarak kırılganlığını en üst düzeye çıkarmalıdır'], 'Linolyum doğal yağ ve reçine içerdiğinden hafif ısıtıldığında yumuşar; bu sayede oyma bıçakları takılmadan akıcı kesimler yapar.'),
  ('Yüksek baskıda geniş beyaz alanları temizlemek için U profilli oluklu bıçaklar tercih edilirken, ince kontur çizgilerini keskin biçimde açmak için hangi uç yapısı kullanılır?', 'Dar açılı V profilli oyma bıçağı', ['Tırtıklı yarım ay biçimli mezzotint beşiği', 'Yuvarlak uçlu çelik parlatma malası', 'Geniş kauçuk ağızlı serigrafi çekeceği'], 'V profilli bıçaklar (veiner/parting tool) linol ve ağaç kalıplarda net, keskin kenarlı ince çizgiler açmak için idealdir.'),
  ('Çukur baskı (intaglio) ailesindeki tüm tekniklerin ortak mürekkepleme ve silme aşaması aşağıdakilerden hangisidir?', 'Mürekkebin oyuklara yedirilip yüksekte kalan parlak yüzeyin tarlatanla temizlenmesi', ['Sert kauçuk merdaneyle yalnızca kabartma sırtların ince bir film halinde boyanması', 'Yağlı boyanın suyla ıslatılmış kireç taşı yüzeyinde çizimsiz bölgelerden itilmesi', 'Sıvı boyanın gözenekli ipek elekten silecek yardımıyla doğrudan kâğıda süzülmesi'], 'Çukur baskıda plakanın tamamına boya sürülür, ardından tarlatan (tülbent) ve gazete/avuç içiyle yüzey silinerek boya yalnızca çukur kanallarda bırakılır.'),
  ('Klasik kalem gravüründe (line engraving) bakır levhayı hiçbir asit kullanmadan doğrudan V kesitli oluklar açarak yontan, mantar saplı çelik araca ne ad verilir?', 'Büren (hakkâk kalemi)', ['Baren (baskı diski)', 'Ragle (boya çekeceği)', 'Lavis (fırça asidi)'], 'Büren (burin), avuç içine oturan mantar saplı ve eşkenar dörtgen kesitli sert çelikten yapılmış geleneksel metal oyma kalemidir.'),
  ('Kuru kazıma (drypoint) tekniğinde çelik veya elmas uçlu iğne metali çizdiğinde kanalın iki yanında kalkan ve baskıda kadifemsi zengin bir siyahlık veren metal kıvrımına ne denir?', 'Çapak (burr)', ['Vernik (lak)', 'Gofre (kabartma)', 'Tram (nokta ağı)'], 'Kuru kazıma iğnesi metali çıkarmak yerine yana doğru iter; oluşan çapak (burr) bol mürekkep tutarak buğulu, kadifemsi çizgiler verir.'),
  ('Akuaforte çalışmasında laklı plakaya iğneyle çizim yapılırken sanatçının metali derinlemesine kazımak yerine yalnızca vernik tabakasını açmasının sebebi nedir?', 'Çizgilerin derinliğini kol gücünün değil, asit banyosunda kalma süresinin belirlemesi', ['Çinko ve bakır plakaların çelik iğneden daha sert bir kristal yapıya sahip olması', 'Derin kazınan kanalların mürekkebi tutmayıp baskıda bembeyaz çıkması', 'İğne metale değdiği anda vernik tabakasının kimyasal reaksiyonla tutuşması'], 'Akuafortede iğne yalnızca koruyucu lakı sıyırır; açılan yerlerdeki metali aşındırarak çukurlaştırma işini asit üstlenir.'),
  ('Çukur baskıda çizgisel tarama yapmaksızın geniş, homojen gri ve siyah ton yüzeyleri elde etmek amacıyla geliştirilen reçine tozlu tekniğin adı nedir?', 'Akuatinta', ['Kuru kazıma', 'Ksilografi', 'Monotip'], '18. yüzyılda Jean-Baptiste Le Prince tarafından geliştirilen akuatinta, plaka üzerine serpilip ısıtılan reçine (kolofonyum) tozları arasındaki boşlukların asitle yedirilmesiyle sulu boya benzeri tonlar üretir.'),
  ('Mezzotint plakası hazırlanırken bakır yüzeyi her yönde binlerce minik oyuk ve çapakla kaplamak için ileri-geri sallanarak yürütülen dişli çelik araca ne ad verilir?', 'Beşik', ['Tarlatan', 'Merdane', 'Baren'], 'Yarım ay biçimli ve ağzı sık dişli çelik bir keski olan \'beşik\' (berceau / rocker), plaka üzerinde onlarca farklı açıda sallanarak kadifemsi mezzotint dokusunu oluşturur.'),
  ('Gravür sanatında sapının ucunda döner dişli küçük bir tekerlek bulunan ve metal plakada noktalı doku kanalları açmaya yarayan araca ne ad verilir?', 'Rulet', ['Büren', 'Ragle', 'Küvet'], 'Rulet (roulette), asitsiz olarak bakır plaka üzerinde noktasal gölgeler ve ton geçişleri üretmek için kullanılan döner dişli el aletidir.'),
  ('Bir özgün baskı resmin sol alt köşesinde kurşun kalemle yazılmış \'14/50\' ibaresi koleksiyoncu ve izleyiciye hangi bilgiyi verir?', 'Toplam 50 adetlik sınırlı edisyonun 14 numaralı baskısı olduğunu', ['Eserin 1950 yılının 14. haftasında basıldığını', 'Plakanın 14 santimetre ene ve 50 santimetre boya sahip olduğunu', 'Baskıda 14 farklı renk kalıbının 50 bar basınçla kullanıldığını'], 'Özgün baskı numaralandırmasında payda toplam basılan edisyon sayısını (tirajı), pay ise o kopyanın sıra numarasını gösterir.'),
  ('Özgün baskı resimlerin altında Fransızca geleneğe göre \'E.A.\' (Épreuve d\'Artiste) veya İngilizce \'A.P.\' harfleriyle işaretlenen kopyalar neyi ifade eder?', 'Ticari edisyon dışında sanatçının kendisine ayrılan sınırlı sayıdaki sanatçı baskılarını', ['Hatalı basıldığı için imha edilmek üzere ayrılmış kusurlu atölye kâğıtlarını', 'Kalıp asitte tamamen eridikten sonra dijital yazıcıyla çoğaltılan kopyaları', 'Sanatçının ölümünden yüzyıl sonra müze tarafından basılan hatıra nüshalarını'], 'E.A. (Épreuve d\'Artiste) veya A.P. (Artist\'s Proof), asıl numaralı edisyonun yaklaşık %10\'unu geçmeyecek şekilde sanatçının arşivi için basılan özgün kopyalardır.'),
  ('Asitle yedirme (akuaforte) yaparken metal plakanın yalnızca ön yüzüne değil, arka yüzüne ve yan kenarlarına da koruyucu lak veya bant uygulanmasının zorunlu nedeni nedir?', 'Asit küvetine daldırılan plakanın arkasından da eriyerek incelmesini ve asidin hızla tükenmesini önlemek', ['Arka yüzeyin pürüzsüz kalması halinde silindir preste kayarak kâğıdı yırtmasını engellemek', 'Baskı mürekkebinin metalin gözeneklerinden sızıp alt tablaya bulaşmasını durdurmak', 'Plakanın ısıtıcı tabla üzerinde bükülmeden düz durabilmesi için ağırlık dengelemesi yapmak'], 'Plaka küvete tamamen daldırıldığından arka yüz ve kenarlar yalıtılmazsa asit çıplak metalin her yerini saldırgan biçimde çözer, çözeltiyi bozar ve levhayı deler.'),
  ('Gravürde aynı yönde paralel çizgilerin üstüne farklı açılarla ikinci ve üçüncü kat çizgilerin işlenmesiyle koyu gölge değerleri oluşturulmasına ne ad verilir?', 'Çapraz tarama (cross-hatching)', ['Açık yedirme (open bite)', 'Kör baskı (gofre)', 'Kumlama (carborundum)'], 'Büren ve akuaforte ustaları, çizgilerin sıklığını ve kesişme katmanlarını artırarak (çapraz tarama) reçine tozu kullanmadan da zengin ışık-gölge dereceleri kurarlar.'),
  ('Linol veya ağaç baskıda oyma bıçağını tutarken boşta kalan elin konumuyla ilgili atölye güvenliğinin en temel altın kuralı nedir?', 'Kalıbı tutan el daima bıçağın kesim yönünün gerisinde kalmalı, önüne asla konulmamalıdır', ['Boştaki el bıçağın ucunu önden çekerek sert yerlerde kesime hız kazandırmalıdır', 'Kalıp dizlerin arasına sıkıştırılıp bıçak vücuda doğru güçlüce çekilmelidir', 'Kaymayı önlemek için kalıp yüzeyine kesimden önce bolca sıvı vazelin sürülmelidir'], 'Yüksek baskı kazıma kazalarının neredeyse tamamı bıçağın aniden kayıp öndeki eli kesmesinden kaynaklanır; bu yüzden destek eli her zaman keski ağzının arkasında durmalı ve tezgâhta dayama takozu (bench hook) kullanılmalıdır.'),
  ('Yüksek baskı tezgâhında kalıbın kesim sırasında ileri kaymasını önlemek amacıyla masanın kenarına takılan Z kesitli ahşap destek tablasına ne ad verilir?', 'Dayama takozu', ['Mezzotint beşiği', 'Reçine dolabı', 'Küvet çerçevesi'], 'Alt ve üst çıtalarıyla masa kenarına kilitlenen dayama takozu (bench hook), elin kalıbı önden tutma ihtiyacını ortadan kaldırarak güvenli oyma olanağı tanır.'),
  ('Merdaneyle cam tabla üzerinde yüksek baskı mürekkebi açılırken doğru kıvam ve kalınlığa ulaşıldığını gösteren görsel-işitsel işaret hangisidir?', 'Boyanın ince kadife dokusu alması ve hafif bir fısıltı (cırtlama) sesi çıkarması', ['Merdanenin cam üzerinde hiç dönmeden tamamen kayarak sessizce ilerlemesi', 'Boya yüzeyinde yarım santimetre yüksekliğinde iri tepecikler ve oluklar belirmesi', 'Mürekkebin köpürerek su gibi kenarlardan masanın altına akmaya başlaması'], 'Cam veya mermer üzerinde merdaneyle ezilen boya fazla olduğunda şapırtılı ses çıkarır; ince ve homojen kadife dokuya indiğinde ise karakteristik hafif bir ipek hışırtısı duyulur.'),
  ('Bir özgün baskı kâğıdının ışığa tutulduğunda lif dokusu içinde beliren, kâğıt üreticisinin adını veya armasını gösteren yarı saydam ize ne ad verilir?', 'Filigran (su izi / watermark)', ['Gofre (kör kabartma)', 'Edisyon mührü', 'Küvet kenarı'], 'Kâğıt üretimi sırasında tel elek üzerine dikilen ince metal motifin o bölgede lifleri daha ince bırakmasıyla oluşan \'filigran\' (watermark), hem kâğıdın kalitesini hem de tarihsel dönemini doğrulamada kritik rol oynar.'),
  ('Gravür veya yüksek baskı kâğıtları pres altından nemli olarak çıktıktan sonra kenarlarının dalgalanıp kıvrılmaması (ondüle olmaması) için nasıl kurutulmalıdır?', 'Temiz kurutma kartonları (blotter) ve düz ağırlık levhaları arasında yavaşça preslenerek', ['Çamaşır ipine mandalla asılıp sıcak saç kurutma makinesiyle hızla üflenerek', 'Doğrudan kızgın kalorifer peteğinin üzerine çıplak halde yatırılarak', 'Rulo şeklinde sıkıca sarılıp plastik bir poşetin ağzı bağlanarak'], 'Nemli pamuklu kâğıt serbest kurursa lifler düzensiz çekerek dalgalanır; nem emici kurutma mukavvaları arasında düz ağırlık altında veya germe tahtasında kurutulduğunda jilet gibi düz kalır.'),
  ('Çukur baskıda çok katı olan gravür mürekkebini plakaya kolayca yayabilmek ve silmeyi yumuşatmak için metal plakanın boyama sırasında yerleştirildiği tezgâh aracına ne denir?', 'Isıtıcı tabla', ['Asit küveti', 'Işıklı pozlama masası', 'Vakumlu serigrafi tezgâhı'], 'Hafifçe ılıtılan ısıtıcı tabla (hot plate) üzerinde bakır plaka ısınır; böylece sert gravür mürekkebi tereyağı gibi yumuşayarak en ince çizgilere nüfuz eder ve yüzeyden rahat silinir.'),
  ('Aşağıdakilerden hangisi bir eserin \'röprodüksiyon\' (fotomekanik çoğaltım) değil, \'özgün baskı resim\' sayılması için aranan temel sanatsal ölçüttür?', 'Görüntünün başka bir tablonun kopyası olmayıp kalıbın bizzat sanatçı tarafından o baskı dili için yaratılması', ['Baskının mutlaka 18. yüzyıldan kalma antika bir ahşap preste çekilmiş olması', 'Eserin yalnızca siyah mürekkeple basılıp hiçbir renkli pigment içermemesi', 'En az on bin adet basılarak günlük gazetelerin eki olarak dağıtılması'], 'Özgün baskı resim (original print), mevcut bir yağlı boya tablonun fotoğrafik kopyası değildir; sanatçının kalıbı doğrudan doğruya yaratım aracı olarak kullandığı bağımsız sanat yapıtıdır.'),
  ('Linol ve ağaç baskıda kauçuk el merdanesinin (brayer) işi bittikten sonra boyalı halde tezgâh üzerine yüzüstü bırakılmayıp sırtındaki ayakları üzerine ters konulmasının nedeni nedir?', 'Kauçuk silindirin tek noktadan ezilip düzleşerek sonraki baskılarda şerit izi bırakmasını önlemek', ['Merdane sapındaki ahşabın havayla temas edip nem kapmasını engellemek', 'Mürekkebin merdane içine doğru emilerek rengini koyulaştırmasını sağlamak', 'Silindirin kendi kendine yuvarlanıp asit küvetinin içine düşmesini kolaylaştırmak'], 'Silindirik kauçuk veya poliüretan merdane ağırlığıyla tezgâha temas ederse ezilip formunu kaybeder (flat spot); bu yüzden metal destek ayakları üzerinde havada tutulur.'),
  ('Pleksiglas (akrilik levha) kalıpların başlangıç düzeyindeki çukur baskı eğitiminde kuru kazıma malzemesi olarak sıkça tercih edilmesinin pedagojik avantajı nedir?', 'Saydam yapısı sayesinde altına konan eskizin doğrudan izlenebilmesi ve kolay çizilebilmesi', ['Nitrik asit banyosunda bakırdan on kat daha hızlı ve duman çıkarmadan erimesi', 'Yüz bin kopyalık edisyon boyunca çapaklarının hiç aşınmadan çelik gibi kalması', 'Isıtıcı tabla üzerinde 200 derecede erimeden sert gravür boyasını kaynatabilmesi'], 'Şeffaf pleksiglas hem ucuzdur hem de altına yerleştirilen çizimi ters çevirmeden doğrudan kopyalamaya olanak tanır; ancak yumuşak olduğu için düşük tirajlı kuru kazıma verir.'),
  ('Geleneksel ksilografide \'beyaz çizgi baskısı\' (white-line woodcut) olarak bilinen yaklaşımda sanatçının bıçakla açtığı tek bir oluk baskı kâğıdında nasıl karşılık bulur?', 'Siyah zemin üzerinde doğrudan doğruya beyaz bir çizgi olarak görünür', ['Beyaz kâğıt üzerinde kalın siyah bir kontur çizgisi olarak belirir', 'Kadifemsi gri gölgelerle çevrili çapaklı bir leke oluşturur', 'Kâğıdı keserek kabartmalı şeffaf bir çerçeve meydana getirir'], 'Siyah çizgi elde etmek için çizginin iki yanını oymak gerekirken, beyaz çizgi ksilografisinde bıçağın açtığı her kanal doğrudan doğruya boya almayan ışıklı bir çizgiye dönüşür.'),
  ('Metal gravür plakasında asit yedirmesi tamamlandıktan sonra yüzeydeki siyah asfalt lakı temizlemek için geleneksel atölyelerde hangi çözücü kullanılır?', 'Terebentin veya mineral tiner', ['Saf kireç suyu', 'Arap zamkı şurubu', 'Yumurta sarısı emülsiyonu'], 'Bitüm (asfalt) ve balmumu bazlı geleneksel sert lak suda çözünmez; terebentin, gaz yağı, white spirit veya çağdaş atölyelerde bitkisel yağlarla (ayçiçeği/kanola yağı) yumuşatılarak silinir.'),
  ('1798 yılında Münih\'te tiyatro metinlerini ucuza çoğaltmanın yollarını ararken düz baskı (litografi) tekniğini icat eden sanatçı ve yazar kimdir?', 'Alois Senefelder', ['Johannes Gutenberg ve ortağı Johann Fust', 'Jean-Baptiste Le Prince ve Ludwig von Siegen', 'Stanley William Hayter ve Thomas Bewick'], 'Alman oyun yazarı Alois Senefelder, 1798\'de Bavyera kireç taşı üzerinde yağ ve suyun birbirini itmesi ilkesine dayanan kimyasal taş baskıyı (litografiyi) bulmuştur.'),
  ('Geleneksel taş baskı (litografi) tekniğinin çalışma prensibi kalıp yüzeyi üzerindeki hangi temel fiziksel-kimyasal ilkeye dayanır?', 'Yağ ile suyun birbirini itmesine', ['Kazınarak yükseltilen sırtların merdaneyle boyanmasına', 'Derin oyuklara doldurulan boyanın tarlatanla silinmesine', 'İpek dokuma gözeneklerinden sıvı mürekkebin süzülmesine'], 'Düz baskı (planografik) ailesinden olan litografide basılacak ve basılmayacak alanlar aynı düzlemdedir; ayrımı yağlı çizim malzemesi ile su tutan zamklı yüzeyin birbirini itmesi sağlar.'),
  ('Litografi baskısı sırasında usta basımcının merdaneyle yağlı mürekkep vermeden hemen önce taşı nemli bir süngerle silmesinin zorunlu nedeni nedir?', 'Boş alanlardaki su filmini yenileyerek merdanedeki boyanın oralara bulaşmasını önlemek', ['Taşın üzerindeki kurumuş baskı mürekkebini yıkayıp kalıbı tamamen temizlemek', 'Kireç taşının sürtünme ısısıyla çatlayıp ikiye ayrılmasını engellemek', 'Kâğıdın taş yüzeyine tutkal gibi yapışarak orada kalmasını sağlamak'], 'Taş kurursa yağlı merdane çizimsiz beyaz alanları da boyar (tinting/scumming); nemli sünger boş yüzeylerde ince bir su tabakası bırakarak boyanın yalnız yağlı çizime tutunmasını sağlar.'),
  ('Litografide ağır Solnhofen taşları yerine ince grenlenmiş alüminyum plakaların kalıp olarak kullanılmasıyla uygulanan düz baskı tekniğine ne ad verilir?', 'Algrafi', ['Kolagrafi', 'Kalsografi', 'Ksilografi'], 'Alüminyum plakalarla yapılan düz baskıya algrafi (algraphy), çinko plakalarla yapılana ise çinkografi denir; taşla aynı yağ-su itmesi prensibine dayanır ancak çok hafif ve taşınabilirdir.'),
  ('19. yüzyılın ikinci yarısında reklam afişleri, kitap levhaları ve popüler resimlerin çoğaltılmasında çığır açan, her renk tonu için ayrı bir taş kalıp hazırlanan tekniğin adı nedir?', 'Kromolitografi', ['Fotogravür', 'Şeker akuatintası', 'Mezzotint baskı'], 'Godefroy Engelmann\'ın patentlediği kromolitografi, bazen on beş-yirmi ayrı taşın kusursuz poza ayarıyla üst üste basılmasıyla canlı renkli ticari ve sanatsal baskılar üretmiştir.'),
  ('19. yüzyıl sonu Paris\'inde Moulin Rouge ve kabare kültürü için tasarladığı sıçratma (crachis) dokulu renkli taş baskı afişleriyle modern afiş sanatının kurucularından sayılan sanatçı kimdir?', 'Henri de Toulouse-Lautrec', ['Albrecht Dürer ve Lucas Cranach', 'Marcantonio Raimondi ve Ugo da Carpi', 'Giovanni Battista Piranesi ve William Hogarth'], 'Toulouse-Lautrec, Japon baskılarından esinlenen yalın lekeleri ve diş fırçasıyla mürekkep sıçratma (crachis) tekniğini kullanarak litografiyi sokak afişi düzeyinden yüksek sanata taşımıştır.'),
  ('Şablon baskı grubunun en gelişmiş üyesi olan \'serigrafi\' (elek baskı / ipek baskı) tekniğinde mürekkep baskı yüzeyine nasıl ulaşır?', 'Çerçeveye gerilmiş dokumanın açık bırakılan gözeneklerinden silecek zoruyla süzülerek', ['Yüksekte kalan ahşap sırtlara sürülen boyanın pres altında ezilmesiyle', 'Bakır plakadaki asit oyuklarından nemli pamuklu kâğıdın boyayı emmesiyle', 'Suyla nemlendirilmiş kireç taşının yağlı bölgelerinden merdaneyle geçmesiyle'], 'Serigrafide (silkscreen) ipek veya polyester eleğin basılmayacak yerleri emülsiyonla tıkanır; açık kalan gözeneklerden ragle (squeegee) aracılığıyla itilen boya alt yüzeye geçer.'),
  ('Serigrafi çerçevesi üzerindeki boyayı gözeneklerden kâğıda aktarmak için kullanılan, ahşap ya da alüminyum sapa takılı esnek poliüretan/kauçuk ağızlı araca ne ad verilir?', 'Ragle', ['Büren', 'Levigatör', 'Rulet'], 'Ragle (squeegee), serigrafide boyayı elek üzerinde süpürerek açık gözeneklerden alt yüzeye basan poliüretan veya kauçuk bıçaklı temel baskı aletidir.'),
  ('Önceleri yalnızca ticari tabela ve ambalaj çoğaltımında kullanılan serigrafi tekniğini, 1960\'larda Marilyn Monroe ve Campbell Çorba Kutuları dizileriyle çağdaş sanatın merkezine taşıyan Pop Art temsilcisi kimdir?', 'Andy Warhol', ['Jackson Pollock ve Mark Rothko', 'Constantin Brâncuși ve Alberto Giacometti', 'Henri Matisse ve André Derain'], 'Andy Warhol, \'Fabrika\' (The Factory) adını verdiği atölyesinde gazete fotoğraflarını foto-serigrafi ile tuval ve kâğıda aktararak seri üretim estetiğini ve bilinçli baskı kaymalarını sanatsal dile dönüştürmüştür.'),
  ('Cam, bakır veya pleksiglas gibi hiçbir oyuk ya da şablon taşımayan pürüzsüz bir levha üzerine yağlı/su bazlı boyayla resim yapılıp kâğıda aktarılmasıyla yalnız tek bir tam baskı veren yönteme ne ad verilir?', 'Monotip', ['Kromolitografi', 'Fotogravür', 'Ksilografi'], '17. yüzyılda Giovanni Benedetto Castiglione\'nin uyguladığı ve 19. yüzyılda Edgar Degas\'nın doruğa çıkardığı monotipte kalıpta kalıcı çizgi yoktur; boya tek geçişte kâğıda geçer ve eser eşsizdir (1/1).'),
  ('17. yüzyıldan 19. yüzyıl ortasına dek Japonya\'nın Edo (Tokyo) döneminde kentli tüccar sınıfının eğlence yaşamını, kabuki aktörlerini ve doğa manzaralarını konu alan geleneksel ağaç baskı sanatına ne ad verilir?', 'Ukiyo-e', ['Sumi-e', 'Kintsugi', 'Origami'], 'Sözlük anlamı \'yüzen/geçici dünyanın resimleri\' olan Ukiyo-e, Edo dönemi Japon kent kültürünün gündelik zevklerini ve manzaralarını yansıtan dünyaca ünlü ağaç baskı ve resim geleneğidir.'),
  ('Dünya sanat tarihinin en tanınmış imgelerinden biri olan \'Kanagawa Açıklarında Büyük Dalga\' adlı ağaç baskı hangi sanatçının hangi baskı dizisi içinde yer alır?', 'Katsushika Hokusai – Otuz Altı Fuji Manzarası', ['Utagawa Hiroshige – Tokaido Yolu\'nun Elli Üç İstasyonu', 'Kitagawa Utamaro – Çay Evinin Ünlü Güzelleri', 'Tōshūsai Sharaku – Kabuki Sahnesinin Aktör Portreleri'], 'Katsushika Hokusai\'nin yaklaşık 1831\'de yayımlanan \'Otuz Altı Fuji Manzarası\' (Fugaku Sanjūrokkei) dizisinin ilk ve en ünlü baskısı, arka planda küçük Fuji Dağı\'nı çerçeveleyen Büyük Dalga\'dır.'),
  ('Kuzey Rönesansı\'nda hem \'Mahşerin Dört Atlısı\' adlı ağaç baskı dizisiyle hem de \'Melencolia I\' ve \'Şövalye, Ölüm ve Şeytan\' adlı bakır kalem gravürleriyle baskı resmi bağımsız bir başyapıt düzeyine çıkaran usta kimdir?', 'Albrecht Dürer', ['Sandro Botticelli', 'Jan van Eyck', 'Caravaggio'], 'Nürnbergli usta Albrecht Dürer (1471-1528), ksilografiye hacimli tarama dilini kazandırmış, bürenle işlediği bakır gravürlerde ise ulaşılması güç bir doku ve ışık zenginliği yakalamıştır.'),
  ('17. yüzyıl Hollanda sanatında akuaforte ile kuru kazımayı aynı bakır plakada özgürce birleştirerek ve plakada bilinçli mürekkep tülü bırakarak \'Üç Haç\' ile \'Yüz Guldenlik Baskı\' gibi başyapıtlar üreten sanatçı kimdir?', 'Rembrandt van Rijn', ['Johannes Vermeer', 'Frans Hals', 'Piet Mondrian'], 'Rembrandt akuaforteyi katı çizgisel kurallardan kurtarmış, kuru kazıma çapaklarıyla ve farklı silme tonlarıyla aynı kalıbın durum baskılarında dramatik ışık-gölge değişimleri yaratmıştır.'),
  ('Ahi-zometri, olanaksız mimariler, hiperbolik döşemeler (tessellation) ve birbirine dönüşen kuş-balık örüntülerini olağanüstü bir matematiksel titizlikle ağaç oyma, linol ve taş baskıya aktaran Hollandalı grafik ustası kimdir?', 'Maurits Cornelis Escher', ['Theo van Doesburg', 'Karel Appel', 'Willem de Kooning'], 'M. C. Escher (1898-1972), sonsuzluk, simetri, yansıma ve perspektif paradokslarını ksilografi, ağaç oyma, mezzotint ve litografi tekniklerinde kusursuz bir zanaatla görselleştirmiştir.'),
  ('Türkiye\'de özgün gravür sanatının öncülerinden olup, kasap kâğıtları ve zımparalar dahil alışılmadık malzemelerle coşkulu, lirik ve dışavurumcu İstanbul oymaları üreten kadın sanatçımız kimdir?', 'Aliye Berger', ['Mihri Müşfik Hanım', 'Hale Asaf', 'Celile Hikmet'], 'Londra\'da John Buckland-Wright\'tan gravür öğrenen Aliye Berger (1903-1974), çizgisel coşkusu ve deneysel baskı kâğıtlarıyla Türk çukur baskı sanatının en özgün ve tutkulu öncüsü olmuştur.'),
  ('Kuşbakışı İstanbul silüetlerini, minyatür istifini andıran ritmik ağaç kümelerini ve göçebe kuş sürülerini çizgisel örgüyle ağaç baskı, serigrafi ve gravüre aktaran çağdaş Türk sanatçısı kimdir?', 'Devrim Erbil', ['Hikmet Onat', 'Feyhaman Duran', 'Zühtü Müridoğlu'], 'Devrim Erbil, geleneksel doğu minyatürünün dikey mekan kurgusunu ve ritmik çizgi tekrarlarını özgün serigrafi, linol ve gravür çalışmalarıyla çağdaş bir kent şiirine dönüştürmüştür.'),
  ('Bir kişinin özel kütüphanesindeki kitapların iç kapağına yapıştırmak üzere sanatçıya özgün baskı teknikleriyle tasarlattığı, üzerinde genellikle \'Ex Libris\' ibaresi ve kitap sahibinin adı bulunan küçük grafik yapıta ne denir?', 'Ekslibris', ['Filigran', 'Kolofon', 'Serlevha'], 'Latince \'...nın kitaplığından\' anlamına gelen ekslibris (kitap mülkiyet etiketi), matbaanın icadından bu yana ağaç oyma, bakır gravür ve litografiyle üretilen köklü bir mikro özgün baskı sanatıdır.'),
  ('Serigrafi şablonu hazırlarken hiçbir kimyasal emülsiyon veya karanlık oda kullanmadan keskin kenarlı geometrik renk lekeleri basmak isteyen bir öğrenci en pratik olarak hangi yöntemi uygulayabilir?', 'Kâğıt veya kendinden yapışkanlı kesme film şablonunu eleğin alt yüzüne tutturmak', ['Eleği nitrik asit dolu küvete batırıp fırçayla geometrik alanları eritmek', 'Polyester dokumayı mum aleviyle yakarak açık pencereler oluşturmak', 'İpek çerçeveyi ağır gravür silindirlerinin arasından geçirerek ezmek'], 'Düşük ve orta tirajlı düz renkli serigrafilerde yağlı/kuşe kâğıttan kesilen şablonlar ilk boya çekişiyle eleğin altına kendiliğinden yapışır ve son derece keskin kenarlı baskılar verir.'),
  ('Baskı işlemi tamamlanmış bir foto-serigrafi eleğindeki sertleşmiş emülsiyonu söküp aynı çerçeveyi yeni bir eser için tekrar kullanmak amacıyla uygulanan kimyasal işleme ne denir?', 'Emülsiyon sökme / elek geri kazanımı (reclaiming)', ['Çelik kaplama (aciérage)', 'Kalıp iptali (biffage)', 'Reçine fırınlama (tavlama)'], 'Boya temizlendikten sonra eleğe periyodat bazlı emülsiyon sökücü (stencil remover) sürülüp basınçlı suyla yıkanarak dokuma tertemiz ilk haline döndürülür.'),
  ('Pop Art hareketinin bir diğer öncüsü Roy Lichtenstein, çizgi roman karelerini dev boyutlu baskılara ve tablolara taşırken matbaa estetiğini simgeleyen hangi görsel dokuyu imzası haline getirmiştir?', 'Ben-Day noktalarını (düzenli tram beneklerini) ve kalın siyah konturları', ['İnce bakır büren çapraz taramalarını ve altın varak haleleri', 'Japon bokashi sulu boya geçişlerini ve mika tozu serpme fonları', 'Kuru kazıma çapaklarının buğulu ve belirsiz duman lekelerini'], 'Benjamin Day\'in 19. yüzyıl sonunda ucuz renkli gazete ve çizgi roman baskısı için geliştirdiği \'Ben-Day noktaları\', Lichtenstein\'ın serigrafi ve şablonlarında anıtsal bir üslup öğesine dönüşmüştür.'),
  ('Serigrafi tezgâhının baskı tablasında yüzlerce ince hava deliğinin bulunması ve altındaki bir motorla hava çekilmesinin (vakumlu tabla) baskı sırasındaki temel yararı nedir?', 'İnce kâğıdın baskı anında kıpırdamadan sabit kalmasını ve boyalı elekle birlikte yukarı kalkmamasını sağlamak', ['Kâğıdın gözeneklerinden boyayı aşağı emerek masanın altındaki ikinci kâğıdı da boyamak', 'Su bazlı boyanın içindeki pigmentleri vakumlayarak rengi açık griye çevirmek', 'Atölyedeki nitrik asit ve terebentin dumanlarını kâğıdın içine hapsetmek'], 'Serigrafi boyası yapışkan olduğundan, vakum tablası kâğıdı alttan tutmazsa çerçeve kaldırıldığında kâğıt eleğin altına yapışıp poza ayarını bozar ve lekelenir.'),
  ('Utagawa Hiroshige\'nin Edo ile imparatorluk başkenti Kyoto\'yu birbirine bağlayan kıyı kara yolundaki konaklama noktalarını mevsim, yağmur, kar ve sis atmosferiyle betimlediği ünlü baskı dizisi hangisidir?', 'Tōkaidō Yolu\'nun Elli Üç İstasyonu', ['Yüz Ünlü Edo Güzeli ve Gece Eğlenceleri', 'Seksen Sekiz Tapınaklı Shikoku Hac Yolu', 'On İki Aylık Samuray Kılıç Talimleri'], 'Hiroshige\'nin 1833-1834 yıllarında yayımlanan \'Tōkaidō Yolu\'nun Elli Üç İstasyonu\' (Tōkaidō Gojūsantsugi) dizisi, şiirsel doğa gözlemi ve yağmur/kar efektleriyle manzara baskısının zirvelerindendir.'),
  ('19. yüzyıl Fransa\'sında siyasi taş baskıları nedeniyle hapis yatan, ardından 4000\'e yakın litografisinde Paris burjuvazisini, yargıçları ve \'Transnonain Sokağı\' trajedisini ölümsüzleştiren sanatçı kimdir?', 'Honoré Daumier', ['Jacques-Louis David', 'Jean-Auguste-Dominique Ingres', 'Pierre-Auguste Renoir'], 'Honoré Daumier (1808-1879), litografi tebeşirinin hızlı ve dışavurumcu gücünü hem keskin siyasi mizah hem de derin insani dramlar için kullanarak taş baskının en üretken ustalarından biri olmuştur.'),
  ('Baskı mürekkeplerinde \'şeffaflık\' (transparanlık) ve \'örtücülük\' (opaklık) dikkate alındığında, siyah çizgi kalıbının (anahtar kalıp) çok renkli bir ağaç baskıda en son basılmasının pratik avantajı nedir?', 'Alt katmandaki renk lekelerinin birleşme sınırlarını toparlayıp ufak poza taşmalarını net konturlarla örtmesi', ['Siyah mürekkebin üstüne başka hiçbir yağlı boyanın fiziksel olarak yapışamaması', 'İlk basılan siyah boyanın kâğıdı büzüştürerek yarı yarıya küçültmesi', 'Renkli boyaların siyah mürekkebi kimyasal olarak eritip tamamen yok etmesi'], 'Çok kalıplı yüksek baskıda genellikle açıktan koyuya gidilir ve örtücü siyah kontur kalıbı en son basılarak renk alanları arasındaki küçük boşluk veya taşmaları toparlayıp formu kilitler.'),
  ('Bir serigrafi sanatçısı koyu siyah bir fon kâğıdı üzerine tek geçişte canlı ve parlak sarı bir motif basmak istediğinde şeffaf boya yerine hangi özellikte mürekkep kullanmalıdır?', 'Yüksek titanyum dioksit/örtücü pigment içeren opak mürekkep', ['Yüzde doksan oranında şeffaf pasta (transparan baz) katılmış sulu boya', 'Hiç pigment içermeyen saf keten tohumu verniği ve kurutucu kobalt', 'Kâğıt liflerinin içine tamamen gömülen seyreltik anilin mürekkebi'], 'Şeffaf boyalar alt zeminin rengini yansıttığından siyah kâğıt üzerinde kaybolup kirli görünür; siyah zeminde parlak renk için ya tam opak serigrafi boyası ya da önce beyaz zemin baskısı gerekir.'),
  ('Atölyede acil ve ekonomik çukur baskı denemeleri yapmak isteyen bir öğrencinin iç yüzeyi alüminyum-polietilen kaplı içecek kartonlarını (Tetra Pak) kuru kazıma kalıbı olarak kullanmasına ne ad verilir?', 'Tetra Pak (karton ambalaj) çukur baskısı', ['Kromolitografik taş transfer baskısı', 'Şimşir kütük enine kesit oyması', 'İpek dokuma emülsiyon pozlaması'], 'İçecek kutularının parlak iç yüzeyi iğneyle çizilmeye, katmanlarının soyularak koyu kadife tonlar vermeye ve ağır silindir preste asitsiz çukur baskı (mutfak/geri dönüşüm gravürü) almaya çok elverişlidir.'),
  ('1990\'lardan itibaren yüksek çözünürlüklü geniş format mürekkep püskürtmeli (inkjet) yazıcılarla arşivsel pigment mürekkepler ve %100 pamuklu asitsiz kâğıtlar kullanılarak yapılan dijital sanat baskılarına ne ad verilir?', 'Giclée', ['Heliogravür', 'Ototip baskı', 'Kalsografi'], 'Fransızca \'püskürtmek\' kökünden türetilen \'giclée\', solmaya dirençli mikro-pigment mürekkeplerin müze kalitesindeki pamuklu kâğıtlara yüksek nokta yoğunluğuyla püskürtüldüğü çağdaş dijital baskı terimidir.'),
  ('Yüksek, çukur, düz ve şablon baskı tekniklerinin tamamında ortak olan \'edisyon tutanağı / dokümantasyon formu\' (print documentation sheet) hangi bilgileri kayıt altına alır?', 'Kullanılan kâğıt ve kalıp türünü, edisyon sayısını, A.P./B.A.T. adetlerini, basımcıyı ve kalıp iptal bilgisini', ['Sanatçının banka hesap dökümünü, atölyenin elektrik faturasını ve çerçevecinin kira sözleşmesini', 'Eseri satın alan tüm koleksiyoncuların ev adreslerini ve kimlik numaralarını', 'Yalnızca atölyenin bulunduğu kentin o günkü hava sıcaklığını ve rüzgâr hızını'], 'Profesyonel baskı atölyeleri (örneğin Tamarind geleneği), eserin özgünlüğünü ve tiraj dürüstlüğünü gelecek kuşaklara kanıtlamak için teknik künye ve edisyon dağılım tutanağı düzenler.'),
  ('Taş baskı, serigrafi, gravür ve yüksek baskı olmak üzere dört ana baskı resim tekniğinden hangisinde kalıptaki görüntü kâğıda basıldığında ayna simetrisiyle TERS DÖNMEZ, kalıpta görüldüğü yönle aynı çıkar?', 'Serigrafi', ['Klasik bakır kalem gravürü', 'Linolyum yüksek baskı', 'Doğrudan Solnhofen taş baskısı'], 'Yüksek, çukur ve doğrudan taş baskıda kalıp kâğıtla yüz yüze kapanıp basıldığı için görüntü ters döner; oysa serigrafide boya üstten eleğin içinden süzülerek altındaki kâğıda doğrudan aynı yönde iner.'),
  ('Bir baskı atölyesinde yüksek baskı, çukur baskı, taş baskı ve serigrafi alanları planlanırken, hangi tekniğin çalışma köşesinde güçlü bir çeker ocak (davlumbazlı havalandırma) bulunması en öncelikli iş güvenliği şartıdır?', 'Nitrik asit ve solvent buharlarının çıktığı geleneksel çukur baskı (asit yedirme) bölümünde', ['Yalnızca kuru pamuklu kâğıtların katlanıp cetvelle yırtıldığı kesim masasında', 'Su bazlı guaj boyaların poşuar fırçasıyla kartona sürüldüğü şablon masasında', 'Kurşun kalemle edisyon numaralarının ve imzaların atıldığı paketleme köşesinde'], 'Nitrik asidin metallerle tepkimesinden çıkan kahverengi-kırmızı azot dioksit gazı ile asfalt lak çözücülerin buharları akciğerler için çok tehlikelidir; asit küvetleri mutlaka çeker ocak altında olmalıdır.'),
  ('Geleneksel gravür veya taş baskı kâğıtları tabaka halinden istenen boyuta küçültülürken makas ya da maket bıçağıyla düz kesmek yerine \'metal cetvel kenarında kâğıt kemiğiyle koparılmasının\' estetik gerekçesi nedir?', 'El yapımı kâğıtların doğal sakallı kenar (deckle edge) görünümünü ve yumuşak lif geçişini korumak', ['Makasın metal ağzının pamuklu kâğıda değdiğinde elektriklenip siyah leke bırakması', 'Bıçakla kesilen kâğıtların nemlendirme suyunda anında eriyerek hamura dönüşmesi', 'Yırtılan kenarların silindir preste çelik merdaneyi bileyerek parlatması'], 'Maket bıçağı keskin ve mekanik bir kenar bırakır; oysa ağır pamuklu baskı kâğıtları cetvel altında kontrollü yırtıldığında lifler uzayarak orijinal sakallı kenarla uyumlu estetik bir saçak oluşturur.'),
  ('Mutfak litografisi (kitchen lithography) olarak bilinen ve Emilie Aizier tarafından yaygınlaştırılan çağdaş alternatif düz baskı yönteminde pahalı kireç taşı ve nitrik asit yerine hangi gündelik malzemeler kullanılır?', 'Alüminyum mutfak folyosu, yağlı kalem/sabun ve asidik kola ya da limon suyu', ['Pişirme kâğıdı, toz şeker şurubu ve çamaşır suyu ağartıcısı', 'Teflon tava yüzeyi, su bazlı parmak boyası ve karbonatlı maden suyu', 'Cam fırın tepsisi, zeytinyağı ve kaynar elma sirkesi buharı'], 'Mutfak litografisi Senefelder\'in yağ-su itmesi ve asidik duyarsızlaştırma ilkesini mat alüminyum folyo ve fosforik/sitrik asit içeren kola/limon ile zehirsiz ve erişilebilir biçimde uygular.'),
  ('Özgün baskı yapıtların çerçevelenmesi ve müze konservasyonunda eserin zamanla kahverengi lekeler (foxing) oluşturup bozulmaması için paspartu ve arka karton seçiminde hangi kurala uyulmalıdır?', '%100 pamuklu, linyinsiz müze kalitesinde asitsiz paspartu kullanılmalı ve kâğıt cama doğrudan değmemelidir', ['Eserin arkası marangoz tutkalıyla ham sunta veya oluklu koli kartonuna tamamen yapıştırılmalıdır', 'Baskı kâğıdının nemini korumak için cam ile kâğıt arasına ıslak sünger şeritleri sıkıştırılmalıdır', 'Kenarlardaki boşluklar ve kurşun kalem imzalar makasla kesilip yalnız resimli kısım bırakılmalıdır'], 'Sıradan mukavva ve ahşap arkalıklardaki asit zamanla özgün baskı kâğıdına geçerek geri dönülmez sararma yapar; ayrıca cama sıfır temas yoğuşma ve küf riski doğurduğundan derin paspartu şarttır.'),
  ('Osmanlı basın tarihinde 1870 yılında Teodor Kasap tarafından yayımlanan ilk Türk mizah dergisi hangisidir?', 'Diyojen', ['Hayal ve Hakikat', 'Çıngıraklı Tatar', 'Karagöz Mecmuası'], 'Diyojen, Teodor Kasap tarafından 1870\'te İstanbul\'da çıkarılan ve Türk basın tarihinin ilk müstakil mizah dergisi kabul edilen yayındır.'),
  ('Cumhuriyet dönemi Türk karikatürünün kurucu kuşağı olarak bilinen "1950 Kuşağı"nın öncü isimlerinden Turhan Selçuk\'un yarattığı dünyaca ünlü çizgi karakter hangisidir?', 'Abdülcanbaz', ['Avanak Avni', 'Gırgır Hafiye', 'Karaoğlan'], 'Turhan Selçuk tarafından yaratılan Abdülcanbaz, İstanbul beyefendisi kimliğiyle kötülere karşı mücadele eden simgeleşmiş bir Türk çizgi karakteridir.'),
  ('Oğuz Aral yönetiminde 1972 yılında yayın hayatına başlayan ve tirajıyla dünya mizah basınında ilk sıralara yerleşen efsanevi Türk mizah dergisi hangisidir?', 'Gırgır', ['Akbaba', 'Markopaşa', 'Zümrüdüanka'], 'Oğuz Aral\'ın yönettiği Gırgır dergisi, sarı renkli kapağı ve genç çizer kadrosuyla Türk mizah dergiciliğinde kitlesel okur rekorları kırmıştır.'),
  ('Kitapseverlerin kitaplarının iç kapağına yapıştırdıkları, üzerinde isimlerinin ve çeşitli sanatsal desenlerin yer aldığı mülkiyet etiketine ne ad verilir?', 'Ekslibris', ['Filigran', 'Minyatür', 'Monogram'], 'Latince "kitaplarından" anlamına gelen ekslibris, kitabın kime ait olduğunu gösteren özgün baskı veya tasarım küçük grafik yapıtlardır.'),
  ('Karikatür kelimesinin kökeni olan İtalyanca "caricare" fiilinin sanatsal bağlamdaki temel anlamı aşağıdakilerden hangisidir?', 'Yüklemek ve abartmak', ['Kopyalamak ve çoğaltmak', 'Gizlemek ve şifrelemek', 'Parlatmak ve süslemek'], 'İtalyanca "caricare" fiili bir şeyi olduğundan fazla yüklemek, abartarak biçimini bozmak anlamına gelir ve karikatürün temel estetiğini açıklar.'),
  ('Sabahattin Ali, Aziz Nesin ve Rıfat Ilgaz\'ın 1946 yılında birlikte çıkardıkları, siyasi taşlamalarıyla Türk basın tarihine geçen mizah gazetesi hangisidir?', 'Markopaşa', ['Kalem Dergisi', 'Dolmuş Mecmuası', 'Tef Dergisi'], 'Markopaşa, çok partili hayata geçiş sürecinde toplumsal ve siyasi eleştirileriyle büyük yankı uyandırmış tarihi mizah gazetesidir.'),
  ('Yusuf Ziya Ortaç ve Orhan Seyfi Orhon tarafından 1922\'de kurulan ve on yıllarca yayımlanarak pek çok çizer yetiştiren ünlü mizah dergisi hangisidir?', 'Akbaba', ['Boşboğaz', 'Papağan', 'Kelebek'], 'Akbaba dergisi, Mütareke döneminden 1977 yılına dek uzun soluklu yayınıyla Cumhuriyet dönemi mizah edebiyatı ve karikatürüne yön vermiştir.'),
  ('Üzerinde konuşma balonu ya da altyazı bulunmayan, mesajını yalnızca çizginin evrensel görsel gücüyle aktaran karikatür anlayışına ne ad verilir?', 'Yazısız karikatür', ['Portre karikatürü', 'Bant karikatürü', 'Editoryal vinyet'], '1950 Kuşağı ile Türkiye\'de de yaygınlaşan yazısız karikatür, dil engelini ortadan kaldırarak grafik espriyi salt çizgiyle kurgular.'),
  ('Bir edebi metni, masalı ya da bilimsel konuyu görsel olarak açıklamak, zenginleştirmek veya yorumlamak amacıyla yapılan resimleme sanatına ne denir?', 'İllüstrasyon', ['Kaligrafi', 'Tipografi', 'Koreografi'], 'İllüstrasyon, yazılı bir metinle organik bağ kurarak okurun zihninde anlatıyı somutlaştıran veya derinleştiren özgün resimleme sanatıdır.'),
  ('Fransa Kralı Louis-Philippe\'i "armut" biçiminde çizerek modern siyasi karikatürün öncüsü kabul edilen 19. yüzyıl Fransız sanatçısı kimdir?', 'Honoré Daumier', ['Gustave Doré', 'Henri de Toulouse-Lautrec', 'Eugène Delacroix'], 'Honoré Daumier, La Caricature ve Le Charivari dergilerindeki keskin taş baskı karikatürleriyle modern politik taşlamanın kurucularından olmuştur.'),
  ('Oğuz Aral\'ın yarattığı, konuşamayan ancak mahallede sürekli ezilmesine rağmen hınzır tepkileriyle güldüren sarı tişörtlü çocuk karakteri hangisidir?', 'Avanak Avni', ['Utanmaz Adam', 'Gaddar Davut', 'Muhlis Bey'], 'Avanak Avni, Oğuz Aral\'ın Gırgır sayfalarında ölümsüzleştirdiği, sessiz ve ezik görünümü altında keskin bir mizah barındıran ikonik tiptir.'),
  ('Lewis Carroll\'ın "Alice Harikalar Diyarında" adlı klasiğinin ilk baskısını resimleyerek karakterlerin görsel hafızasını oluşturan Viktorya dönemi çizeri kimdir?', 'John Tenniel', ['Arthur Rackham', 'Beatrix Potter', 'Aubrey Beardsley'], 'Sör John Tenniel, Punch dergisinin baş çizeri olmasının yanı sıra Alice Harikalar Diyarında için yaptığı ahşap gravür illüstrasyonlarla tanınır.'),
  ('Ekslibris tasarımlarında geleneksel olarak yer alan Latince "Ex Libris" ibaresinden hemen sonra hangi bilginin yazılması esastır?', 'Kitap sahibinin adı', ['Kitabın basım tarihi', 'Matbaanın bulunduğu şehir', 'Yazarın mahlası veya imzası'], '"Ex Libris Mehmet Yılmaz" örneğinde olduğu gibi ibare doğrudan "...\'nın kitaplığından" anlamını tamamlamak üzere mülkiyet sahibinin adını taşır.'),
  ('Türk karikatürünün kurucu ustalarından Cemal Nadir Güler\'in halk arasında çok sevilen, göbekli, fesli ve hazırcevap İstanbullu tiplemesi hangisidir?', 'Amca Bey', ['Ramiz Bey', 'Köylü Ağa', 'Şaban Efendi'], 'Cemal Nadir Güler\'in 1929\'da yarattığı Amca Bey, dönemin toplumsal değişimlerine nüktedan gözlemlerle yaklaşan ilk yerli karikatür tiplerindendir.'),
  ('"Tavşan Peter\'in Masalı" adlı eseri hem yazıp hem de suluboya tekniğiyle resimleyen ünlü İngiliz çocuk kitabı illüstratörü kimdir?', 'Beatrix Potter', ['Kate Greenaway', 'Quentin Blake', 'Maurice Sendak'], 'Beatrix Potter, doğa gözlemlerine dayanan zarif hayvan suluboyalarıyla modern resimli çocuk kitabının en önemli öncülerinden biridir.'),
  ('Rönesans döneminde insan yüzündeki fizyonomik deformasyonları ve grotesk ifadeleri inceleyen çizimleriyle karikatürün habercisi sayılan usta kimdir?', 'Leonardo da Vinci', ['Sandro Botticelli', 'Piero della Francesca', 'Raffaello Sanzio'], 'Leonardo da Vinci\'nin "grotesk başlar" olarak bilinen eskizleri, abartılı yüz hatlarını etüt ederek karikatür sanatına zemin hazırlamıştır.'),
  ('Portre karikatüründe çizerin modelin benzerliğini kaybetmeden karakteristik özelliklerini öne çıkarması hangi ilkeyle açıklanır?', 'Seçici abartma', ['Geometrik simetri', 'Fotogerçekçi kopyalama', 'Perspektif sıfırlama'], 'Portre karikatüründe burun, bakış veya çene gibi ayırt edici hatlar seçilerek abartılırken kişinin kimliğini ele veren oran ilişkisi korunur.'),
  ('Roald Dahl\'ın "Matilda", "Koca Sevimli Dev" ve "Charlie\'nin Çikolata Fabrikası" gibi kitaplarını enerjik mürekkep çizgileriyle resimleyen sanatçı kimdir?', 'Quentin Blake', ['Edward Gorey', 'Ralph Steadman', 'Norman Rockwell'], 'Quentin Blake\'in özgür, titrek ve hareketli çini mürekkebiyle suluboya birleşimi tarzı, Roald Dahl\'ın mizahi dünyasıyla bütünleşmiştir.'),
  ('Saint-Exupéry\'nin dünyaca ünlü "Küçük Prens" kitabının orijinal baskısındaki suluboya illüstrasyonları kim yapmıştır?', 'Antoine de Saint-Exupéry', ['Jean-Jacques Sempé', 'Albert Uderzo', 'René Goscinny'], 'Küçük Prens\'in yazarı Antoine de Saint-Exupéry, metinle ayrılmaz bir bütün oluşturan yalın ve şiirsel suluboya resimlerini de bizzat çizmiştir.'),
  ('Orta Çağ el yazması kitaplarında sayfa kenarlarına veya baş harflerin içine altın varak ve parlak boyalarla yapılan süsleme ve resimlemeye ne ad verilir?', 'Tezhip ve minyatürleme', ['Tipo baskı dizgisi', 'Kolografi oyma', 'Litografik transfer'], 'Latince "aydınlatmak" kökünden gelen illüminasyon ve Doğu\'daki karşılığı tezhip-minyatür geleneği, matbaa öncesi kitap illüstrasyonunun temelidir.'),
  ('II. Meşrutiyet\'in ilanından hemen sonra 1908\'de yayınlanan ve Türk-Avrupa karikatür etkileşiminde köprü kuran çift dilli (Türkçe-Fransızca) mizah dergisi hangisidir?', 'Kalem', ['Çaylak', 'Latife', 'Curcuna'], 'Salah Cimcoz ve Celal Esat Arseven\'in çıkardığı Kalem dergisi, Cem (Cemil Cem) gibi ustaları yetiştirerek Batılı anlamda modern karikatürü yerleştirmiştir.'),
  ('Gazetelerin başyazı veya yorum sayfalarında güncel bir siyasi ya da toplumsal olayı tek karede eleştirel biçimde yorumlayan karikatür türü hangisidir?', 'Editoryal (siyasi) karikatür', ['Sürekli macera bandı', 'Fانتastik illüstrasyon', 'Kaligrafik amblem'], 'Editoryal karikatür, gazetecilik etiği ve mizah estetiğini birleştirerek gündemdeki bir sorunu çarpıcı görsel metaforlarla sorgular.'),
  ('Japon Edo döneminde gelişen ve kelime anlamı "yüzen dünya resimleri" olan geleneksel renkli ahşap baskı sanatına ne ad verilir?', 'Ukiyo-e', ['Sumi-e', 'Origami', 'İkebana'], 'Ukiyo-e, Edo dönemi Japon kent kültürünü, kabuki oyuncularını, geyşaları ve doğa manzaralarını konu alan dünyaca ünlü ahşap kalıp baskı sanatıdır.'),
  ('Katsushika Hokusai\'nin "Fuji Dağı\'nın Otuz Altı Manzarası" serisinde yer alan ve dünya sanat tarihinin en tanınmış ukiyo-e baskısı olan eser hangisidir?', 'Kanagawa Açıklarında Büyük Dalga', ['Geceleyin Kafe Terası', 'Nilüferler Göleti', 'İzlenim: Gün Doğumu'], 'Kanagawa Açıklarında Büyük Dalga, dev pençeli dalgaların arasında kayıkları ve arka plandaki sakin Fuji Dağı\'nı gösteren ikonik ahşap baskıdır.'),
  ('Yağ ile suyun birbirini itmesi ilkesine dayanan ve kireçtaşı levha üzerinden yapılan düz baskı tekniğine ne ad verilir?', 'Litografi (Taş baskı)', ['Ksilografi (Ağaç baskı)', 'Serigrafi (İpek baskı)', 'Linolyum baskı'], '1796\'da Alois Senefelder tarafından icat edilen litografi (taş baskı), kazıma gerektirmeden yağlı kalemle taş üzerine doğrudan çizim yapılmasına olanak tanır.'),
  ('İnce dokunmuş ipek ya da sentetik elek bezinden rakle yardımıyla boyanın süzülerek yüzeye aktarıldığı şablon baskı tekniği hangisidir?', 'Serigrafi', ['Akuaforte', 'Mezzotinta', 'Kuru kazıma'], 'İpek baskı olarak da bilinen serigrafi, elek gözeneklerinin açık kalan kısımlarından mürekkebin kağıt, kumaş veya cam yüzeye geçirilmesiyle uygulanır.'),
  ('Pop Art akımının öncüsü Andy Warhol\'un Marilyn Monroe ve Campbell Çorba Konservesi eserlerini çoğaltırken kullandığı temel baskı tekniği hangisidir?', 'Serigrafi', ['Taş baskı', 'Bakır gravür', 'Ağaç oyma'], 'Andy Warhol, ticari reklam dünyasından aldığı serigrafi (ipek baskı) tekniğini tüketim kültürünün seri üretim estetiğini yansıtmak için kullanmıştır.'),
  ('Çizgi roman sayfalarında ardışık iki panel (kare) arasında kalan ve okurun zihninde zaman-mekan geçişini tamamladığı boşluğa ne ad verilir?', 'Oluk', ['Konuşma balonu', 'Efekt yazısı', 'Altyazı kutusu'], 'İngilizce "gutter" (oluk/aralık) olarak adlandırılan panel arası beyaz boşluk, iki hareketsiz resmi okurun hayal gücünde kesintisiz harekete dönüştürür.'),
  ('Çizgi romanda bir karakterin içinden geçirdiği düşünceleri yüksek sesli konuşmadan ayırmak için konuşma balonu genellikle hangi biçimde çizilir?', 'Bulut biçimli ve küçük halkalarla karaktere bağlanan balon', ['Testere dişli keskin köşelere sahip patlama balonu', 'Kalın dikdörtgen çerçeveli düz sarı anlatıcı kutusu', 'Kesik çizgilerle çevrili fısıltı balonu'], 'Bulut formundaki balon ve karaktere uzanan küçük kabarcıklar, çizgi roman dilinin evrensel görsel sözlüğünde iç sesi (düşünceyi) simgeler.'),
  ('Belçikalı çizer Hergé\'nin genç bir gazeteci ve beyaz köpeği Milu\'nun maceralarını anlattığı dünyaca ünlü çizgi roman serisi hangisidir?', 'Tenten\'in Maceraları', ['Asteriks ve Oburiks', 'Şirinler', 'Spirou ve Fantasio'], 'Hergé (Georges Remi) tarafından 1929\'da yaratılan Tenten, Avrupa çizgi roman ekolünün (bande dessinée) en temel klasiğidir.'),
  ('Suat Yalaz tarafından 1962 yılında yaratılan ve Orta Asya\'dan dünyaya yayılan serüvenleriyle tanınan ünlü Türk tarihi çizgi roman kahramanı kimdir?', 'Karaoğlan', ['Tarkan', 'Malkoçoğlu', 'Kara Murat'], 'Suat Yalaz\'ın çizdiği Karaoğlan, Fransa dahil pek çok ülkede yayımlanmış ve sinemaya da uyarlanmış Türk çizgi roman tarihinin en güçlü karakterlerindendir.'),
  ('Sezgin Burak tarafından yaratılan, sadık kurdu ile birlikte Hun İmparatoru Attila\'nın savaşçısı olarak maceralara atılan ünlü Türk çizgi roman kahramanı kimdir?', 'Tarkan', ['Karaoğlan', 'Tolga', 'Yüzbaşı Volkan'], 'Sezgin Burak\'ın güçlü anatomik çizgileriyle hayat verdiği Tarkan ve kurdu, 1967\'den itibaren günlük gazetelerde ve dergilerde büyük ilgi görmüştür.'),
  ('Asitle yedirme yöntemiyle metal (bakır veya çinko) levha üzerine uygulanan çukur baskı tekniğinin İtalyanca "güçlü su / kezzap" anlamına gelen adı nedir?', 'Akuaforte', ['Guaj boya', 'Tempera', 'Fresko'], 'Akuaforte (gravür/etching), aside dayanıklı vernikle kaplı metal plakanın iğneyle çizilip asit banyosunda çukurlaştırılmasıyla yapılan çukur baskı tekniğidir.'),
  ('Çizgi romanlarda "GÜM!", "ÇAT!", "VIZZZ!" gibi sesleri görsel harf büyüklüğü ve dinamik tasarımla sahnenin içine yerleştiren öğelere ne ad verilir?', 'Yansıma ses (Onomatope) efektleri', ['Bölüm başlığı serlevhası', 'Yazar biyografisi dipnotu', 'Sayfa numarası filigranı'], 'Onomatope (yansıma sözcükler), sessiz bir mecra olan çizgi romanda işitsel şiddeti, hızı ve yönü grafik tipografi aracılığıyla okura duyurur.'),
  ('Japon çizgi roman sanatına dünyaca verilen genel ad aşağıdakilerden hangisidir?', 'Manga', ['Manhwa', 'Bande dessinée', 'Fumetti'], 'Köken olarak Hokusai\'nin eskiz defterlerinde popülerleşen "manga" terimi, sağdan sola okunan özgün Japon çizgi roman geleneğini ifade eder.'),
  ('Nazi Soykırımı\'nı (Holokost) Yahudileri fare, Nazileri kedi olarak betimleyerek anlatan ve Pulitzer Ödülü kazanan "Maus" adlı grafik romanın yazarı ve çizeri kimdir?', 'Art Spiegelman', ['Will Eisner', 'Alan Moore', 'Frank Miller'], 'Art Spiegelman, babası Vladek\'in Auschwitz anılarını çizgi roman diliyle aktararak 1992\'de Pulitzer Özel Ödülü\'nü kazanmış ve grafik romanın edebi saygınlığını kanıtlamıştır.'),
  ('İran İslam Devrimi\'ni ve sonrasındaki göç sürecini kendi çocukluk ve gençlik anıları üzerinden siyah-beyaz çizgilerle anlatan "Persepolis" adlı grafik roman kime aittir?', 'Marjane Satrapi', ['Alison Bechdel', 'Posy Simmonds', 'Rutu Modan'], 'Marjane Satrapi\'nin otobiyografik grafik romanı Persepolis, yalın dışavurumcu siyah-beyaz estetiğiyle hem edebiyat hem de animasyon dünyasında klasikleşmiştir.'),
  ('René Goscinny ve Albert Uderzo ikilisinin yarattığı, sihirli iksir içerek Roma lejyonlarına direnen Galya köyünün başkahramanı hangisidir?', 'Asteriks', ['Red Kit', 'Gaston', 'Marsupilami'], '1959\'da Pilote dergisinde doğan Asteriks, tarihsel anakronizm ve kelime oyunlarıyla Fransız-Belçika çizgi roman ekolünün zirvelerinden biridir.'),
  ('Yüksek baskı (örneğin ağaç baskı) ile çukur baskı (örneğin akuaforte) arasındaki en temel mürekkepleme farkı nedir?', 'Yüksek baskıda yüksekte kalan yüzeyler, çukur baskıda ise kazınan oluklar mürekkep alır', ['Yüksek baskıda yalnızca su bazlı boya, çukur baskıda ise yalnızca toz tebeşir kullanılır', 'Yüksek baskı sadece cam üzerine, çukur baskı ise sadece ipek kumaş üzerine uygulanır', 'Yüksek baskıda pres makinesi kullanılmazken çukur baskıda fırçayla elle boyama yapılır'], 'Ağaç veya linol baskıda oyulmayan tümsek kısımlar kağıda boya verirken; gravür ve akuafortede yüzey silinir, pres basıncıyla kağıt çukurlardaki boyayı emer.'),
  ('Paris\'teki Moulin Rouge kabaresi için yaptığı renkli taş baskı (litografi) afişlerle modern afiş ve baskı sanatında devrim yaratan Fransız ressam kimdir?', 'Henri de Toulouse-Lautrec', ['Claude Monet', 'Georges Seurat', 'Paul Cézanne'], 'Toulouse-Lautrec, ukiyo-e baskılarından esinlenen cesur silüetleri ve sıçratma (crachis) tekniğiyle litografiyi sokaklardan müzelere taşımıştır.'),
  ('Modern Japon mangasının ve animesinin "babası" kabul edilen, "Astro Boy" (Tetsuwan Atom) ve "Buda" gibi eserlerin yaratıcısı usta çizer kimdir?', 'Osamu Tezuka', ['Hayao Miyazaki', 'Katsuhiro Otomo', 'Naoki Urasawa'], '"Manga Tanrısı" unvanıyla anılan Osamu Tezuka, sinematografik kamera açılarını ve iri dışavurumcu göz estetiğini manga diline yerleştirmiştir.'),
  ('Özgün baskı resimlerin sol alt köşesine kurşun kalemle yazılan "12/50" gibi bir kesir ifadesi sanat piyasasında ve müzecilikte neyi gösterir?', 'Toplam 50 adetlik sınırlı baskı (edisyon) serisinin 12. nüshası olduğunu', ['Eserin 1950 yılının Aralık ayında tamamlandığını', 'Kağıdın eninin 12 santimetre, boyunun 50 santimetre olduğunu', 'Kalıbın 12 dakika asitte bekletilip 50 derecede kurutulduğunu'], 'Özgün baskıda sanatçı kalıptan basılacak toplam sayıyı (edisyon) belirler, her baskıyı tek tek numaralandırıp imzaladıktan sonra kalıbı iptal eder.'),
  ('Çizgi roman sayfalarında hikâyenin her bir anını çerçeve içine alarak sırayla sunan görsel karelere ne ad verilir?', 'Panel', ['Diyalog akışını bölen beyaz şerit', 'Kapak tasarımındaki başlık bloğu', 'Baskı kalıbının metal çerçevesi'], 'Çizgi romanlarda her bir görsel sahneyi çevreleyen kutulara panel adı verilir.'),
  ('Çizgi romanlarda iki panel arasında kalan ve okuyucunun zaman geçişini zihninde tamamladığı boşluğa ne ad verilir?', 'Oluk', ['Konuşma kutusunun alt kenarı', 'Sayfa numarasının yazıldığı köşe', 'Baskı merdanesinin döndüğü oyuk'], 'Paneller arasındaki boşluk oluk (gutter) olarak adlandırılır ve sahneler arası geçişi sağlar.'),
  ('Çizgi romanda karakterin ağzından çıkan sözleri göstermek için genellikle ok veya kuyrukla karaktere bağlanan biçime ne denir?', 'Konuşma balonu', ['Anlatıcı bilgisi içeren dikdörtgen', 'Arka plan seslerini gösteren harf', 'Sayfanın tamamını kaplayan çerçeve'], 'Karakterlerin sesli diyalogları konuşma balonu içinde verilir.'),
  ('Çizgi romanlarda karakterin dışa vurmadığı iç sesini belirtmek için bulutsu kenarlar ve küçük yuvarlaklarla çizilen unsur hangisidir?', 'Düşünce balonu', ['Köşeli anlatıcı metin kutusu', 'Çift çizgili bağırış çerçevesi', 'Kesikli kenarlı fısıltı balonu'], 'İç monolog ve düşünceler bulut formunda ve küçük baloncuklarla karaktere bağlanan düşünce balonuyla gösterilir.'),
  ('Çizgi romanda "ÇAT!", "GÜM!" veya "ŞRAK!" gibi doğa ve eylem seslerini taklit eden görsel yazı öğelerine ne ad verilir?', 'Onomatope', ['Tipografik sayfa başlığı', 'Baskı serisi numarası', 'Karakter profil şeması'], 'Ses yansımalarını harflerin biçimi ve hareketiyle aktaran öğeler onomatope (yansıma sözcük) olarak bilinir.'),
  ('Bir çizgi romanda sayfanın tamamını tek bir büyük görselle kaplayarak dramatik vurgu yaratan sayfaya ne ad verilir?', 'Splash sayfa', ['Küçük panelli diyalog sayfası', 'Sadece metinden oluşan önsöz', 'Kapak içi künye bölümü'], 'Tek bir görselle tüm sayfayı kaplayan çarpıcı düzenleme splash sayfa (tam sayfa illüstrasyon) olarak adlandırılır.'),
  ('Frankofon kültürün, özellikle Fransa ve Belçika merkezli köklü çizgi roman geleneğine verilen uluslararası ad nedir?', 'Bande dessinée', ['Amerikan süper kahraman dergisi', 'İngiliz politik mizah gazetesi', 'Japon haftalık siyah beyaz dergi'], 'Fransa ve Belçika\'da gelişen çizgi roman geleneği bande dessinée (BD) olarak anılır.'),
  ('Oğuz Aral\'ın Gırgır dergisinde yarattığı, konuşmadan yalnızca bakışları ve jestleriyle toplumu gözlemleyen ünlü çizgi karakteri kimdir?', 'Avanak Avni', ['Bıyıklı mahalle bekçisi tiplemesi', 'Kurnaz şehirli tüccar karakteri', 'Gözlüklü tarih profesörü figürü'], 'Avanak Avni, Oğuz Aral\'ın Gırgır sayfalarında yarattığı unutulmaz ve simgesel mizah karakteridir.'),
  ('Türk karikatürünün öncülerinden Cemal Nadir Güler\'in yarattığı, sıradan halkın sağduyusunu temsil eden ünlü tip hangisidir?', 'Amcabey', ['Zengin konak sahibi efendi', 'Avrupa görmüş diplomat figürü', 'Genç üniversite öğrencisi karakteri'], 'Cemal Nadir Güler\'in 1929\'da doğan Amcabey tiplemesi Türk karikatür tarihinin en bilinen simgelerindendir.'),
  ('Osmanlı döneminin ilk Türkçe mizah gazetesi kabul edilen ve 1870 yılında Teodor Kasap tarafından yayımlanan gazete hangisidir?', 'Diyojen', ['Karagöz ve Hacivat Mecmuası', 'İstanbul Güzel Sanatlar Gazetesi', 'Haftalık Taş Baskı Albümü'], 'Teodor Kasap\'ın çıkardığı Diyojen, Osmanlı basın tarihinde ilk Türkçe mizah gazetesi olarak yer alır.'),
  ('Japonya\'da özellikle genç erkek okur kitlesini hedefleyen, aksiyon ve dostluk temalarının öne çıktığı manga türü hangisidir?', 'Shōnen', ['Seinen yetişkin seçkisi', 'Josei kadın öyküleri', 'Gekiga tarihsel dramı'], 'Shōnen mangaları genç erkek okurlara yöneliktir ve macera, rekabet ile büyüme temalarını işler.'),
  ('Karikatür sanatında bir kişinin yüzündeki belirgin özellikleri tanınabilirliği koruyarak bilinçli biçimde abartma yöntemine ne ad verilir?', 'Deformasyon', ['Fotografik kopyalama', 'Geometrik ölçekleme', 'Klasik oranlama'], 'Karikatürde fiziksel ve karakter özelliklerinin mizahi ya da eleştirel biçimde abartılması deformasyon ilkesine dayanır.'),
  ('Çizgi roman ve illüstrasyonda tek bir karakterin önden, yandan ve arkadan görünüşünü orantı tutarlılığı için aynı sayfada gösteren çalışma hangisidir?', 'Model sayfası', ['Renk ayrım haritası', 'Tam sayfa manzara', 'Baskı kalıbı provası'], 'Model sayfası (turnaround / character sheet), farklı sahnelerde veya çizerlerce karakterin oranlarının tutarlı kalmasını sağlar.'),
  ('Çizgi romanlarda bir karakterin fısıldayarak konuştuğunu belirtmek için konuşma balonunun dış çizgisi genellikle nasıl çizilir?', 'Kesikli çizgilerle', ['Kalın tırtıklı dikenlerle', 'Çift katlı siyah şeritle', 'Dalgalı sulu boya lekesiyle'], 'Kesikli (noktalı) hatlarla çevrili balon ve küçük punto metin, fısıltıyı veya alçak ses tonunu görsel olarak ifade eder.'),
  ('Baskı resim sanatında mürekkebin kalıbın oyulmamış yüksek yüzeyine sürülerek kâğıda aktarıldığı baskı grubuna ne ad verilir?', 'Yüksek baskı', ['Çukur gravür baskısı', 'Düz taş baskı yöntemi', 'Elek baskı tekniği'], 'Ağaç baskı ve linol baskı gibi yüksek baskı (rölyef) tekniklerinde basılacak alanlar yüksekte bırakılır, basılmayacak yerler oyulur.'),
  ('Mürekkebin metal plaka üzerinde açılan çukur çizgi ve oyuklara doldurulup yüksek basınçlı presle kâğıda aktarıldığı baskı türü hangisidir?', 'Çukur baskı', ['Yüksek ahşap baskı', 'Düz litografi baskısı', 'Şablon elek baskısı'], 'Gravür, asit yedirme, akuatinta ve mezzotint gibi çukur baskı (intaglio) tekniklerinde mürekkep oyuklardan kâğıda geçer.'),
  ('Yağ ve suyun birbirini itmesi (karışmaması) kimyasal ilkesine dayanarak düz kireçtaşı yüzeyi üzerinden yapılan baskı tekniği hangisidir?', 'Litografi', ['Linol yüksek baskısı', 'Kuru kazı gravürü', 'Bakır asit indirme'], 'Litografi (taş baskı), yağlı kalemle çizilen alanların mürekkebi tutması ve ıslak taş alanların mürekkebi itmesi esasına dayanır.'),
  ('Ağaç baskıya benzeyen ancak ahşap yerine daha yumuşak ve damarsız muşamba benzeri bir malzemenin oyulmasıyla yapılan yüksek baskı tekniği hangisidir?', 'Linol baskı', ['Bakır gravür baskısı', 'Kireçtaşı litografisi', 'İpek elek baskısı'], 'Linolyum levha yumuşak ve yönsüz dokusu sayesinde her yönde kolayca oyularak linol baskı (linocut) üretimine imkân tanır.'),
  ('1796 yılında kireçtaşı üzerinde litografi (taş baskı) tekniğini icat eden Alman oyun yazarı ve mucit kimdir?', 'Alois Senefelder', ['Johannes Gutenberg', 'Albrecht Dürer Usta', 'William Hogarth Sanatçı'], 'Alois Senefelder, ucuz nota ve oyun metni basmanın yolunu ararken tesadüfen litografi tekniğini keşfetmiştir.'),
  ('Özgün bir baskı resmin altında kurşun kalemle yazılan "12/50" ifadesi neyi belirtir?', 'Toplam 50 adetlik sınırlı edisyonun 12. baskısı olduğunu', ['Eserin 50 farklı sanatçıdan 12\'si tarafından imzalandığını', 'Kalıbın 12 santimetre eninde ve 50 santimetre boyunda olduğunu', 'Baskıda 12 ayrı renk ve 50 katman vernik kullanıldığını'], 'Edisyon numarasında pay baskının sırasını, payda ise o kalıptan basılan toplam sınırlı kopya sayısını gösterir.'),
  ('Japonya\'da Edo döneminde gelişen, "geçici dünyanın resimleri" anlamına gelen ve çoğunlukla çok renkli ahşap baskı tekniğiyle üretilen sanat akımı hangisidir?', 'Ukiyo-e', ['Bande dessinée', 'Art Nouveau afişi', 'Sosyal gerçekçi gravür'], 'Ukiyo-e, Edo dönemi kent yaşamını, kabuki oyuncularını, güzel kadınları ve manzaraları konu alan ünlü Japon baskı geleneğidir.'),
  ('"Kanagawa\'nın Büyük Dalgası" adlı dünyaca ünlü ahşap baskı eseriyle tanınan Japon ukiyo-e ustası kimdir?', 'Katsushika Hokusai', ['Osamu Tezuka Çizeri', 'Albrecht Dürer Ustası', 'Rembrandt van Rijn'], 'Katsushika Hokusai\'nin "Fuji Dağı\'nın Otuz Altı Görünümü" serisindeki Büyük Dalga, dünya sanat tarihinin en ikonik baskılarındandır.'),
  ('"Şövalye, Ölüm ve Şeytan", "Melankoli I" ve "Aziz Hieronymus Çalışma Odasında" adlı üç ünlü bakır gravürüyle Kuzey Rönesansı\'na damga vuran Alman sanatçı kimdir?', 'Albrecht Dürer', ['Hans Holbein Genç', 'Lucas Cranach Baba', 'Matthias Grünewald'], 'Albrecht Dürer, hem ağaç baskı hem de bakır oyma gravürde teknik mükemmelliğe ulaşarak baskı resmi bağımsız yüksek sanat düzeyine taşımıştır.'),
  ('17. yüzyıl Hollanda sanatında hem yağlı boyada hem de özellikle asit yedirme (ofort) ve kuru kazı gravürlerinde olağanüstü ışık-gölge ustalığı gösteren ressam kimdir?', 'Rembrandt van Rijn', ['Johannes Vermeer', 'Frans Hals Portreci', 'Pieter Bruegel Baba'], 'Rembrandt, üç yüzü aşkın gravüründe chiaroscuro etkisini asit yedirme ve kuru kazı kombinasyonlarıyla eşsiz bir anlatım gücüne kavuşturmuştur.'),
  ('"Aklın Uykusu Canavarlar Yaratır" adlı ünlü baskısını da içeren "Kaprisler" (Los Caprichos) serisinin yaratıcısı İspanyol sanatçı kimdir?', 'Francisco Goya', ['Diego Velázquez', 'El Greco Ressamı', 'Bartolomé Esteban Murillo'], 'Francisco Goya, 1799\'da yayımlanan Los Caprichos serisinde asit yedirme ve akuatintayı birleştirerek dönemin bağnazlığını ve akıldışılığını eleştirmiştir.'),
];
